//** [ API TEMPLATE FOR COMBINATORIAL MODELS ] **/
// MODEL_RTL            It is on refmodel directory.
// INPUT_SIGNAL_NAME    List of input signals.
// OUTPUT_SIGNAL_NAME   List of output signals.

#include "VALU.h"             // Header generated by Verilator
#include "verilated.h"        // Verilator support
#include "verilated_vcd_c.h"  // Waveform files for Verilator

// Pointer to DUT (Device Under Test)
VALU* dut = nullptr;
// Pointer to export waveforms
VerilatedVcdC* tfp = nullptr;
// Modern context handler
VerilatedContext* contextp = nullptr;

extern "C" {
    // Evaluate
    void sim_eval() {
        dut->eval();  // Evaluate the model
    }

    // Dump waveform
    void dump(){
        sim_eval();
        tfp->dump(contextp->time());
        contextp->timeInc(1);
    }

    // Apply reset
    void reset() {
        dut -> ex_datars1_i = 0;
        dut -> ex_datars2_i = 0;
        dut -> ex_aluop_i = 0;
        sim_eval();
    }

    // Initialize DUT
    void init() {
        contextp = new VerilatedContext;

        dut = new VALU(contextp);
        tfp = new VerilatedVcdC();

        Verilated::traceEverOn(true);
        dut->trace(tfp, 2); // Signals deep
        tfp->open("dut_signals.vcd");
    }

    // Finalize the simulation
    void finalize() {
        sim_eval();
        if (tfp) {
            tfp->close();
            delete tfp;
            tfp = nullptr;
        }
        if (dut) {
            delete dut;
            dut = nullptr;
        }
        if (contextp) {
            delete contextp;
            contextp = nullptr;
        }
    }



    /*############ SETTERS (for inputs) ############*/
    void set_ex_datars1_i(long ex_datars1_i){
        dut->ex_datars1_i = ex_datars1_i;
        sim_eval();
    }

    void set_ex_datars2_i(long ex_datars2_i){
        dut->ex_datars2_i = ex_datars2_i;
        sim_eval();
    }

    void set_ex_aluop_i(long ex_aluop_i){
        dut->ex_aluop_i = ex_aluop_i;
        sim_eval();
    }


    /*############ GETTERS (for outputs) ############*/
    long get_ex_zerof_o() {
        return dut->ex_zerof_o;
    }

    long get_ex_data_o() {
        return dut->ex_data_o;
    }
}

